/// The fitted field.
///
/// Built by the unchecked constructor because every argument is a literal in this file;
/// `sdtm_reference.rs` puts the same four through `Thermosphere::from_coefficients` and
/// asserts it accepts them, which is where the refusals bind.
pub const FIELD: Thermosphere<HARMONICS> = Thermosphere::from_fitted(
    COEFFICIENTS,
    2e-05,
    1.0,
    StormKernel {
        onset: 2888.069101892565,
        recovery: 9817.366539616045,
    },
);

/// Log-scale offset of the second mission in the fit, reported rather than applied: the model
/// is the physics, and this number is what the two measurement methods disagree by.
pub const MISSION_SCALE: f64 = -0.029916321120004433;

/// Spread of `ln(rho_model/rho_measured)` by regime, from the **calendar-month** held-out
/// residual -- see `DensityUncertainty` for why that split and not the other one.
